def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    if maxsize <= 0:
        raise ValueError("maxsize must be > 0")
    if ttl <= 0:
        raise ValueError("ttl must be > 0")

    def wrapper(function):
        cache = dict()
        cache_ttl = dict()
        hits = misses = 0

        def get_stamp():
            return timer()

        def clear_expired(stamp):
            expired = []
            for key in cache_ttl:
                ttl = cache_ttl[key]
                if stamp < ttl:
                    expired.append(key)
            for key in expired:
                del cache[key]
                del cache_ttl[key]

        @wraps(function)
        def decorated(*args, **kwargs):
            nonlocal hits, misses
            stamp = get_stamp()
            clear_expired(stamp)
            key = (args, kwargs) if typed else args
            if key in cache:
                hits += 1
                value = cache[key]
                cache_ttl[key] = stamp + ttl
                return value
            else:
                misses += 1
                value = function(*args, **kwargs)
                cache[key] = value
                cache_ttl[key] = stamp + ttl
                return value

        def cache_info():
            return {
                "hits": hits,
                "misses": misses,
                "maxsize": maxsize,
                "size": len(cache),
                "ttl": ttl,
            }

        decorated.cache_info = cache_info
        return decorated

    return wrapper
