    def decorator(func):
        cache = {}
        last_access = []
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            try:
                value = cache[key]
            except KeyError:
                value = func(*args, **kwargs)
                cache[key] = value
                last_access.append((args, kwargs, value))
            else:
                last_access.remove((args, kwargs, value))
                last_access.append((args, kwargs, value))
            return value
