def deep_merge_nodes(nodes):
    # Create a dictionary to store the merged nodes
    merged_nodes = {}

    # Iterate through the list of nodes
    for node in nodes:
        # Unpack the current node into its key and value
        key, value = node

        # Check if the key is already in the merged nodes
        if key in merged_nodes:
            # If it is, check if the value is a MappingNode
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                # If it is, recursively merge the values
                merged_nodes[key] = deep_merge_nodes([merged_nodes[key], value])
            else:
                # If it's not a MappingNode, use the last value in the nodes list
                # (i.e., "last value wins")
                merged_nodes[key] = value
        else:
            # If the key is not in the merged nodes, add it to the dictionary
            merged_nodes[key] = value

    # Convert the merged nodes dictionary back into a list of tuples
    return [(k, v) for k, v in merged_nodes.items()]

