    args_dict = {}
    remaining_arguments = []

    while unparsed_arguments:
        argument = unparsed_arguments.pop(0)
        for subparser_name, subparser in subparsers_ready.items():
            try:
                args = [argument] + unparsed_arguments
                parsed_args = subparser.parse_args(args)
