    {
        throw new ArgumentNullException(nameof(seq));
    }

    if (bufsize.HasValue && bufsize <= 0)
    {
        throw new ArgumentOutOfRangeException(nameof(bufsize));
    }

    Type seqType = seq.GetType();
    if (seqType.IsArray || seqType.IsGenericType && seqType.GetGenericTypeDefinition() == typeof(List<>))
    {
        return (seq, seqType);
    }
    else if (!seqType.IsConstructedGenericType || seqType.GetGenericTypeDefinition() != typeof(IEnumerable<>))
    {
        throw new InvalidOperationException($"{seq.GetType().Name} is not a sequence.");
    }

    Type genType = seqType.GetGenericArguments()[0];
    var seqList = (List<object>)Activator.CreateInstance(typeof(List<>).MakeGenericType(genType));
    var enumerator = genType.GetEnumerator();
    while (enumerator.MoveNext())
    {
        seqList.Add(enumerator.Current);
    }

    return (seqList, typeof(List<>).MakeGenericType(genType));
